SELECT CASE WHEN city IN ('London', 'Bangkok') THEN 'core' ELSE 'other' END AS city_group, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, SORT_ARRAY(COLLECT_SET(city)) AS city_list, MIN(rating) AS min_rating FROM suppliers WHERE rating BETWEEN 2.8 AND 3.6 OR supplier_name NOT LIKE '%Parts%' GROUP BY CASE WHEN city IN ('London', 'Bangkok') THEN 'core' ELSE 'other' END, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END HAVING MIN(rating) > 2.3;
